1: import React from "react";
2: import {
3:   Streamdown,
4:   defaultRehypePlugins,
5:   defaultRemarkPlugins,
6: } from "streamdown";
7: import remarkCitationParser from "@/utils/remarkCitationParser";
8: import CopyButton from "./CopyButton";
9: import type { BundledLanguage } from "shiki";
10: import { highlighter } from "@/lib/highlighter";
11: 
12: interface StreamingMarkdownContentProps {
13:   content: string;
14:   isStreaming?: boolean;
15:   size?: "sm" | "md" | "lg";
16:   browserToolResult?: { page_stack: string[] };
17: }
18: 
19: // Helper to extract text from React nodes
20: const extractText = (node: React.ReactNode): string => {
21:   if (typeof node === "string") return node;
22:   if (typeof node === "number") return String(node);
23:   if (!node) return "";
24:   if (React.isValidElement(node)) {
25:     const props = node.props as { children?: React.ReactNode };
26:     if (props?.children) {
27:       return extractText(props.children as React.ReactNode);
28:     }
29:   }
30:   if (Array.isArray(node)) {
31:     return node.map(extractText).join("");
32:   }
33:   return "";
34: };
35: 
36: const safeRehypePlugins = [defaultRehypePlugins.katex];
37: 
38: const CodeBlock = React.memo(
39:   ({ children }: React.HTMLAttributes<HTMLPreElement>) => {
40:     // Extract code and language from children
41:     const codeElement = children as React.ReactElement<{
42:       className?: string;
43:       children: React.ReactNode;
44:     }>;
45:     const language =
46:       codeElement.props.className?.replace(/language-/, "") || "";
47:     const codeText = extractText(codeElement.props.children);
48: 
49:     // Synchronously highlight code using the pre-loaded highlighter
50:     const tokens = React.useMemo(() => {
51:       if (!highlighter) return null;
52: 
53:       try {
54:         return {
55:           light: highlighter.codeToTokensBase(codeText, {
56:             lang: language as BundledLanguage,
57:             theme: "one-light",
58:           }),
59:           dark: highlighter.codeToTokensBase(codeText, {
60:             lang: language as BundledLanguage,
61:             theme: "one-dark",
62:           }),
63:         };
64:       } catch (error) {
65:         console.error("Failed to highlight code:", error);
66:         return null;
67:       }
68:     }, [codeText, language]);
69: 
70:     return (
71:       <div className="relative bg-neutral-100 dark:bg-neutral-800 rounded-2xl overflow-hidden my-6">
72:         <div className="flex select-none">
73:           {language && (
74:             <div className="text-[13px] text-neutral-500 dark:text-neutral-400 font-mono px-4 py-2">
75:               {language}
76:             </div>
77:           )}
78:           <CopyButton
79:             content={codeText}
80:             showLabels={true}
81:             className="copy-button text-neutral-500 dark:text-neutral-400 bg-neutral-100 dark:bg-neutral-800 ml-auto"
82:           />
83:         </div>
84:         {/* Light mode */}
85:         <pre className="dark:hidden m-0 bg-neutral-100 text-sm overflow-x-auto p-4">
86:           <code className="font-mono text-sm">
87:             {tokens?.light
88:               ? tokens.light.map((line, i: number) => (
89:                   <React.Fragment key={i}>
90:                     {line.map((token, j: number) => (
91:                       <span
92:                         key={j}
93:                         style={{
94:                           color: token.color,
95:                         }}
96:                       >
97:                         {token.content}
98:                       </span>
99:                     ))}
100:                     {i < tokens.light.length - 1 && "\n"}
101:                   </React.Fragment>
102:                 ))
103:               : codeText}
104:           </code>
105:         </pre>
106:         {/* Dark mode */}
107:         <pre className="hidden dark:block m-0 bg-neutral-800 text-sm overflow-x-auto p-4">
108:           <code className="font-mono text-sm">
109:             {tokens?.dark
110:               ? tokens.dark.map((line, i: number) => (
111:                   <React.Fragment key={i}>
112:                     {line.map((token, j: number) => (
113:                       <span
114:                         key={j}
115:                         style={{
116:                           color: token.color,
117:                         }}
118:                       >
119:                         {token.content}
120:                       </span>
121:                     ))}
122:                     {i < tokens.dark.length - 1 && "\n"}
123:                   </React.Fragment>
124:                 ))
125:               : codeText}
126:           </code>
127:         </pre>
128:       </div>
129:     );
130:   },
131: );
